238: 	/* Test whether an edit variable has been added to the solver.
239: 
240: 	*/
241: 	bool hasEditVariable( const Variable& variable ) const
242: 	{
243: 		return m_edits.find( variable ) != m_edits.end();
244: 	}
245: 
246: 	/* Suggest a value for the given edit variable.
247: 
248: 	This method should be used after an edit variable as been added to
249: 	the solver in order to suggest the value for that variable.
250: 
251: 	Throws
252: 	------
253: 	UnknownEditVariable
254: 		The given edit variable has not been added to the solver.
255: 
256: 	*/
257: 	void suggestValue( const Variable& variable, double value )
258: 	{
259: 		auto it = m_edits.find( variable );
260: 		if( it == m_edits.end() )
261: 			throw UnknownEditVariable( variable );
262: 
263: 		DualOptimizeGuard guard( *this );
264: 		EditInfo& info = it->second;
265: 		double delta = value - info.constant;
266: 		info.constant = value;
267: 
268: 		// Check first if the positive error variable is basic.
269: 		auto row_it = m_rows.find( info.tag.marker );
270: 		if( row_it != m_rows.end() )
271: 		{
272: 			if( row_it->second->add( -delta ) < 0.0 )
273: 				m_infeasible_rows.push_back( row_it->first );
274: 			return;
275: 		}
276: 
277: 		// Check next if the negative error variable is basic.
278: 		row_it = m_rows.find( info.tag.other );
279: 		if( row_it != m_rows.end() )
280: 		{
281: 			if( row_it->second->add( delta ) < 0.0 )
282: 				m_infeasible_rows.push_back( row_it->first );
283: 			return;
284: 		}
285: 
286: 		// Otherwise update each row where the error variables exist.
287: 		for (const auto & rowPair : m_rows)
288: 		{
289: 			double coeff = rowPair.second->coefficientFor( info.tag.marker );
290: 			if( coeff != 0.0 &&
291: 				rowPair.second->add( delta * coeff ) < 0.0 &&
292: 				rowPair.first.type() != Symbol::External )
293: 				m_infeasible_rows.push_back( rowPair.first );
294: 		}
295: 	}
