297: 	/* Update the values of the external solver variables.
298: 
299: 	*/
300: 	void updateVariables()
301: 	{
302: 		auto row_end = m_rows.end();
303: 
304: 		for (auto &varPair : m_vars)
305: 		{
306: 			Variable& var = varPair.first;
307: 			auto row_it = m_rows.find( varPair.second );
308: 			if( row_it == row_end )
309: 				var.setValue( 0.0 );
310: 			else
311: 				var.setValue( row_it->second->constant() );
312: 		}
313: 	}
