341: 
342: 	struct RowDeleter
343: 	{
344: 		template<typename T>
345: 		void operator()( T& pair ) { delete pair.second; }
346: 	};
347: 
348: 	void clearRows()
349: 	{
350: 		std::for_each( m_rows.begin(), m_rows.end(), RowDeleter() );
351: 		m_rows.clear();
352: 	}
