777: 	/* Remove the effects of a constraint on the objective function.
778: 
779: 	*/
780: 	void removeConstraintEffects( const Constraint& cn, const Tag& tag )
781: 	{
782: 		if( tag.marker.type() == Symbol::Error )
783: 			removeMarkerEffects( tag.marker, cn.strength() );
784: 		if( tag.other.type() == Symbol::Error )
785: 			removeMarkerEffects( tag.other, cn.strength() );
