788: 	/* Remove the effects of an error marker on the objective function.
789: 
790: 	*/
791: 	void removeMarkerEffects( const Symbol& marker, double strength )
792: 	{
793: 		auto row_it = m_rows.find( marker );
794: 		if( row_it != m_rows.end() )
795: 			m_objective->insert( *row_it->second, -strength );
796: 		else
797: 			m_objective->insert( marker, -strength );
798: 	}
